"""`Transparent`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'Transparent'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_backface_culling_lightprobe_volume': False,
        })

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (300.0, 300.0),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', props={
        'location': (11.104004, 277.83487),
    })

    t.link('Transparent BSDF', 'BSDF', 'Material Output', 'Surface')
    return t
